USE smart_ev_parking;

SET SQL_SAFE_UPDATES = 0;
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE APPLIES_ELECTRIC_TARIFF;
TRUNCATE TABLE CHARGING_SESSION;
TRUNCATE TABLE EV_SESSION;
TRUNCATE TABLE REGULAR_SESSION;
TRUNCATE TABLE PARKING_SESSION;
TRUNCATE TABLE RESERVATION;
TRUNCATE TABLE ELECTRIC_VEHICLE;
TRUNCATE TABLE INTERNAL_COMBUSTION_VEHICLE;
TRUNCATE TABLE VEHICLE;
TRUNCATE TABLE EV_SLOT;
TRUNCATE TABLE REGULAR_SLOT;
TRUNCATE TABLE PARKING_SLOT;
TRUNCATE TABLE PARKING_AREA;
TRUNCATE TABLE PARKING_RATE;
TRUNCATE TABLE TARIFF_RATE;
TRUNCATE TABLE `USER`;
SET FOREIGN_KEY_CHECKS = 1;
SET autocommit = 0;

























































































UPDATE RESERVATION SET status = 'PENDING' WHERE reservation_id BETWEEN 17901 AND 18000;
UPDATE PARKING_SLOT SET status = 'AVAILABLE';
UPDATE PARKING_SLOT ps JOIN RESERVATION r ON ps.slot_id = r.slot_id SET ps.status = 'RESERVED' WHERE r.status = 'PENDING';
UPDATE PARKING_SLOT ps JOIN (
    SELECT ev.slot_id FROM EV_SESSION ev JOIN PARKING_SESSION s ON ev.session_id = s.session_id WHERE s.session_status = 'ACTIVE'
    UNION ALL
    SELECT rg.slot_id FROM REGULAR_SESSION rg JOIN PARKING_SESSION s ON rg.session_id = s.session_id WHERE s.session_status = 'ACTIVE'
) active_slots ON ps.slot_id = active_slots.slot_id SET ps.status = 'OCCUPIED';

COMMIT;
SET autocommit = 1;
SET SQL_SAFE_UPDATES = 1;
